//! The memory layout of native Corvid values.
//!
//! Native code generated by `corvid-codegen-cl` and the runtime's Rust
//! code that builds or reads native values (structural equality, typed
//! JSON decoding) both use these constants, so the two sides cannot
//! disagree about where a field or a tag lives.
//!
//! Every heap value is a payload behind a 16-byte header
//! `[refcount | typeinfo]`; a value pointer points at the payload.

/// Bytes per field slot in a record or sum-type variant payload. Ints
/// and pointers fill the slot, a Float is stored as its bits, and a
/// Bool occupies the low byte.
pub const SLOT_BYTES: i32 = 8;

/// A `Result<T, E>` wrapper: the tag at offset 0, one payload slot at 8.
pub const RESULT_PAYLOAD_BYTES: i64 = 16;
pub const RESULT_TAG_OFFSET: i32 = 0;
pub const RESULT_PAYLOAD_OFFSET: i32 = 8;
pub const RESULT_TAG_OK: i64 = 0;
pub const RESULT_TAG_ERR: i64 = 1;

/// A wrapper-backed `Option<T>` (wide scalars and nested options):
/// `None` is the null pointer and `Some` holds one payload slot.
pub const OPTION_PAYLOAD_BYTES: i64 = 8;
pub const OPTION_PAYLOAD_OFFSET: i32 = 0;

/// Payload bytes for a record with `fields` fields.
pub const fn record_payload_bytes(fields: usize) -> i64 {
    (fields as i64) * (SLOT_BYTES as i64)
}

/// Payload bytes for a sum-type variant: the tag slot, then its fields.
pub const fn variant_payload_bytes(fields: usize) -> i64 {
    record_payload_bytes(1 + fields)
}
